import React, { useEffect, useState } from "react";
import api from "../api/api";
import { useAuth } from "../context/AuthContext";

export default function OwnerDashboard(){
  const { user } = useAuth();
  const [stores, setStores] = useState([]);
  const [ratingsForStore, setRatingsForStore] = useState(null);

  useEffect(()=>{ load(); }, []);

  const load = async () => {
    try {
      const res = await api.get("/stores");
      const owned = res.data.stores.filter(s => s.owner && s.owner.id === user.id);
      setStores(owned);
    } catch (err) { console.error(err); alert("Error loading owner data"); }
  };

  const openRatings = async (store) => {
    try {
      const res = await api.get(`/ratings/owner/${store.id}`);
      setRatingsForStore({ store, data: res.data });
    } catch (err) { console.error(err); alert("Error loading ratings"); }
  };

  

  return (
    <div style={{padding:20}}>
      <h2>Owner Dashboard</h2>
      <div>
        <h3>Your Stores</h3>
        <ul>
          {stores.map(s => <li key={s.id}>{s.name} — Avg: {s.averageRating} <button onClick={()=>openRatings(s)}>View Ratings</button></li>)}
        </ul>
      </div>

      {ratingsForStore && (
        <div style={{marginTop:20}}>
          <h3>Ratings for {ratingsForStore.store.name} — Avg: {ratingsForStore.data.averageRating}</h3>
          <ul>
            {ratingsForStore.data.ratings.map(r=>(
              <li key={r.id}><strong>{r.user.name}</strong>: {r.value} — {r.comment || ""}</li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}
